import{_ as a,o,c as i,j as e,a as r}from"./chunks/framework.RRduUuAx.js";const m=JSON.parse('{"title":"Approach","description":"","frontmatter":{"title":"Approach"},"headers":[],"relativePath":"about/approach/index.md","filePath":"about/approach/index.md"}'),s={name:"about/approach/index.md"};function n(l,t,h,p,d,c){return o(),i("div",null,[...t[0]||(t[0]=[e("h1",{id:"approach",tabindex:"-1"},[r("Approach "),e("a",{class:"header-anchor",href:"#approach","aria-label":'Permalink to "Approach"'},"​")],-1),e("p",null,"My work begins with method, not with tools or deliverables. Before building anything — a framework, a pipeline, an evaluation — I try to make explicit what question is being asked, what assumptions the question carries, and what would count as a satisfactory answer. This orientation is slow at the start and faster later, because the analytical structure is already in place when implementation begins.",-1),e("p",null,"I work through layered disclosure. Public documentation on this site describes methods, frameworks, and tools at a level that supports interpretation and potential reuse. It explains what something does, why it is structured that way, and what limits apply. Full operational detail — internal logic, prompt structures, implementation code — is not always included. This is intentional. The public layer is meant to be intellectually honest without being exhaustively complete.",-1),e("p",null,"I prefer rigour over completeness. A method that is clearly defined within stated bounds is more useful than one that claims to cover everything but cannot be inspected. I would rather document what a framework does well and where it breaks down than present a polished surface that hides the difficult parts. Analytical work that cannot be questioned is not analytical work.",-1),e("p",null,"This site reflects that preference. Pages vary in depth. Some describe mature methods with worked examples. Others are placeholders or working notes. The variation is part of the approach: publish what is ready to be read, flag what is not, and revise as the work develops.",-1)])])}const w=a(s,[["render",n]]);export{m as __pageData,w as default};
